function load(){try{const raw=localStorage.getItem('valdora-save');if(!raw)return;const d=JSON.parse(raw);Object.assign(state,d);state.nearby=null;state.toastTimer=null;refreshStats();toast(t('loaded'))}catch(e){console.warn('Save could not be loaded',e)}}
function refreshStats(){state.weight=Object.entries(state.inventory).reduce((n,[id,q])=>n+q*(itemMeta[id]?.weight||1),0);state.maxHp=100+state.skills.vigor*15;state.hp=Math.min(state.hp,state.maxHp);state.damage=4+state.skills.blade+(state.weapon==='Lâmina de ferro'||state.weapon==='Iron blade'||state.weapon==='Hoja de hierro'?3:0);state.armorRating=state.armor==='Gibão reforçado'||state.armor==='Reinforced gambeson'||state.armor==='Jubón reforzado'?2:0}
function addXP(n){state.xp+=n;while(state.xp>=state.nextXp){state.xp-=state.nextXp;state.level++;state.points++;state.nextXp=Math.floor(state.nextXp*1.35);state.maxStamina+=5;state.stamina=state.maxStamina;toast(t('levelUp'))}renderHud()}
function addItem(id,n){const max=n*(itemMeta[id]?.weight||1);if(state.weight+max>state.capacity){toast(t('full'));return false}state.inventory[id]=(state.inventory[id]||0)+n;refreshStats();renderHud();return true}
function useCost(cost){for(const [id,n] of Object.entries(cost))if((state.inventory[id]||0)<n)return false;for(const [id,n] of Object.entries(cost))state.inventory[id]-=n;refreshStats();return true}
function showZone(){const z=zoneAt(state.x);let name=t(z==='village'?'village':z==='ruins'?'ruins':z==='cave'?'cavern':'woodland');$('#zone-label').textContent=name.toUpperCase();$('#location-name').textContent=name;}
function zoneAt(x){return x<850?'forest':x<1220?'village':x<2200?'ruins':'cave'}
function renderHud(){refreshStats();$('#health-fill').style.width=`${100*state.hp/state.maxHp}%`;$('#health-text').textContent=`${Math.ceil(state.hp)} / ${state.maxHp}`;$('#stamina-fill').style.width=`${100*state.stamina/state.maxStamina}%`;$('#stamina-text').textContent=`${Math.ceil(state.stamina)} / ${state.maxStamina}`;$('#level-badge').textContent=state.level;$('#level-number').textContent=state.level;$('#xp-label').textContent=`${state.xp} / ${state.nextXp} XP` ;$('#xp-fill').style.width=`${100*state.xp/state.nextXp}%`;$('#coin-count').textContent=state.coins;$('#inventory-weight').textContent=`${state.weight.toFixed(state.weight%1?1:0)} / ${state.capacity}`;$('#capacity-fill').style.width=`${Math.min(100,100*state.weight/state.capacity)}%`;$('#capacity-fill').style.background=state.weight>=state.capacity?'#be625a':'#bca164';$('#weapon-name').textContent=state.weapon;$('#armor-name').textContent=state.armor;$('#power-stat').textContent=state.damage;$('#resource-list').innerHTML=['wood','stone','ore','herb'].map(id=>`<div class="resource ${state.inventory[id]?'':'empty'}"><span class="resource-icon">${itemMeta[id].icon}</span><div><b>${state.inventory[id]||0}</b><small>${t(id)}</small></div></div>`).join('');updateQuest();updateInteraction();renderTab()}
function updateQuest(){const title=t('questTitle');$('#quest-title').textContent=title;const status=$('#quest-state');let txt=state.quest==='new'?t('questNew'):state.quest==='active'?t('questActive'):t('questDone');status.textContent=txt;status.style.color=state.quest==='done'?'#9aad82':'';status.style.borderColor=state.quest==='done'?'#627655':'';let desc=state.quest==='new'?t('questStart'):t('questDesc');$('#quest-description').textContent=desc;let prog=state.quest==='new'?t('talkToMaera'):state.quest==='active'?`${t('woodProgress')}: ${Math.min(state.inventory.wood||0,5)}/5　 ·　 ${t('wolfProgress')}: ${state.wolfQuest}/1`:state.quest==='ready'?t('questComplete'):state.quest==='done'?t('questPaid'):t('questDesc');$('#quest-progress').innerHTML=`<span>${state.quest==='done'?'✓':'◇'}</span><span>${prog}</span>`}
function updateInteraction(){let candidates=[...world.npcs.map(n=>({x:n.x,type:n.type})),...world.nodes.filter(n=>n.amount>0).map(n=>({x:n.x,type:'node',node:n})),...world.enemies.filter(e=>e.alive).map(e=>({x:e.x,type:'enemy',enemy:e}))];let near=candidates.filter(o=>Math.abs(o.x-state.x)<78).sort((a,b)=>Math.abs(a.x-state.x)-Math.abs(b.x-state.x))[0]||null;state.nearby=near;let label=near?(near.type==='maera'?t('npcMaera'):near.type==='merchant'?t('npcMerchant'):near.type==='node'?`${t('gather')} ${t(near.node.type)}`:t('wolf')):t('explore');$('#nearby-label').textContent=label;$('#interact-prompt').textContent=near?`[ E ]  ${label}`:'';$('#interact-prompt').classList.toggle('show',!!near)}
function renderTab(){const root=$('#tab-content');$$('.tab').forEach(b=>b.classList.toggle('active',b.dataset.tab===state.activeTab));if(state.activeTab==='craft'){root.innerHTML=`<div class="section-title"><h2>${t('craftTitle')}</h2><small>${t('available')}</small></div><p class="section-desc">${t('craftDesc')}</p><div class="recipe-list">${recipes.map(r=>{let name=t(`craft${r.id[0].toUpperCase()+r.id.slice(1)}`),desc=t(`craft${r.id[0].toUpperCase()+r.id.slice(1)}Desc`),ok=Object.entries(r.cost).every(([i,n])=>(state.inventory[i]||0)>=n),cost=Object.entries(r.cost).map(([i,n])=>`${itemMeta[i].icon}${n}`).join(' '),levelOk=state.level>=r.unlock;return `<div class="recipe"><div class="recipe-icon">${r.icon}</div><div class="recipe-info"><b>${name}</b><small>${desc}${levelOk?'':` · Nível ${r.unlock}`}</small></div><div class="recipe-cost">${cost}</div><button data-craft="${r.id}" ${ok&&levelOk?'':'disabled'}>${ok&&levelOk?t('make'):levelOk?t('need'):t('level')+' '+r.unlock}</button></div>`}).join('')}</div><div class="panel-note">✦ ${t('notCrafted')}</div>`;root.querySelectorAll('[data-craft]').forEach(b=>b.onclick=()=>craft(b.dataset.craft))}
else if(state.activeTab==='skills'){let skills=[['blade','⚔','weaponSkill','weaponSkillDesc'],['forager','❋','gatherSkill','gatherSkillDesc'],['vigor','♥','vitalSkill','vitalSkillDesc']];root.innerHTML=`<div class="section-title"><h2>${t('skillsTitle')}</h2><small>${t('points')}</small></div><p class="section-desc">${t('skillsDesc')}</p><div class="skill-points"><span>${t('points')}</span><b>${state.points}</b></div>${skills.map(([id,ic,n,d])=>`<div class="skill-row"><div class="skill-icon">${ic}</div><div><b>${t(n)} <span style="color:#c6a45f;font:9px var(--mono)">Lv.${state.skills[id]}</span></b><small>${t(d)}</small></div><button data-skill="${id}" ${state.points?'':'disabled'}>+1</button></div>`).join('')}<div class="panel-note">✦ ${t('noPoints')}</div>`;root.querySelectorAll('[data-skill]').forEach(b=>b.onclick=()=>upgrade(b.dataset.skill))}
else{root.innerHTML=`<div class="section-title"><h2>${t('journalTitle')}</h2><small>01 / 04</small></div><div class="journal-card"><small>${t('questLog')}</small><h3>${t('questTitle')}</h3><p>${t(state.quest==='new'?'questStart':'questDesc')}</p></div><div class="journal-card"><small>${t('worldLog')}</small><p>${t('journalLore')}</p><p style="margin-top:8px">${[state.discovered.forest?'●':'○',state.discovered.village?'●':'○',state.discovered.ruins?'●':'○',state.discovered.cave?'●':'○'].join('　')}<br>${t('woodland')} · ${t('village')} · ${t('ruins')} · ${t('cavern')}</p></div><div class="journal-card"><small>${t('controls')}</small><p>${t('controlsDesc')}</p></div><button class="journal-action" id="journal-inventory">${t('inventory')} ↗</button>`;$('#journal-inventory').onclick=openInventory}}
function craft(id){const r=recipes.find(x=>x.id===id);if(!r||!useCost(r.cost)){toast(t('notEnough'));return}if(id==='blade'){state.weapon=t('craftBlade');state.damage+=3}else if(id==='axe')state.axe=true;else if(id==='armor'){state.armor=t('craftArmor');state.armorRating=2}else if(id==='potion')state.inventory.potion++;else if(id==='camp'){world.campfires.push({x:state.x});state.hp=Math.min(state.maxHp,state.hp+15)}refreshStats();addXP(12);toast(t('crafted'));renderHud()}
function upgrade(id){if(state.points<=0)return;state.points--;state.skills[id]++;if(id==='vigor'){state.maxHp+=15;state.hp+=15}refreshStats();renderHud()}

