function attack(){if(state.attackCooldown>0||state.stamina<8)return;state.attackCooldown=.36;state.stamina-=8;const target=world.enemies.filter(e=>e.alive&&Math.abs(e.x-state.x)<78&&Math.sign(e.x-state.x)===state.facing).sort((a,b)=>Math.abs(a.x-state.x)-Math.abs(b.x-state.x))[0];if(target){target.hp-=state.damage;target.aggro=true;shake=3;toast(`${t('attackText')} −${state.damage}`);if(target.hp<=0){target.alive=false;state.wolfQuest++;state.coins+=8;addXP(35);if(Math.random()<.75)addItem('hide',1);checkQuest()} }renderHud()}
