function drawLandmarks(){const landmarks=[{x:940,type:'house'},{x:1085,type:'house'},{x:1790,type:'ruin'},{x:2010,type:'ruin'},{x:2780,type:'cave'}];for(const l of landmarks){let x=l.x-camera;if(x<-140||x>canvas.width+140)continue;if(l.type==='house'){rect(x-41,world.ground-83,82,72,'#3b3730');rect(x-52,world.ground-91,104,17,'#272b27');for(let k=0;k<4;k++)rect(x-42+k*27,world.ground-86,17,5,'#55483a');rect(x-13,world.ground-40,26,40,'#211f1a');rect(x+21,world.ground-64,11,14,'#d7a65b');rect(x-35,world.ground-62,11,13,'#d7a65b');rect(x-5,world.ground-90,12,10,'#4d4840')}else if(l.type==='ruin'){rect(x-40,world.ground-98,13,98,'#40433a');rect(x+28,world.ground-80,14,80,'#3a3f38');rect(x-47,world.ground-104,27,9,'#565447');rect(x+20,world.ground-86,29,9,'#555344');rect(x-30,world.ground-70,59,9,'#3b4139');rect(x-29,world.ground-40,13,11,'#777455')}else{rect(x-66,world.ground-22,132,22,'#171c1a');ctx.fillStyle='#101715';ctx.beginPath();ctx.moveTo(x-66,world.ground-18);ctx.lineTo(x-31,world.ground-90);ctx.lineTo(x+31,world.ground-90);ctx.lineTo(x+66,world.ground-18);ctx.fill();rect(x-40,world.ground-18,80,18,'#090e0d');rect(x-25,world.ground-8,50,5,'#322b23')}}}
